-
-// Interfaces (matching QtdVendas.tsx)
-interface DailySale {
-    date: string;
-    quantity: number;
-    weekday: string;
-    avgPrice?: number;
-    total?: number;
-}
-
-interface ProductHistory {
-    productName: string;
-    productCode: string;
-    category: string;
-    categoryType?: string;
-    storeName: string;
-    salesHistory: DailySale[];
-    isFromDb?: boolean;
-}
-
-interface ProductionForecastDashboardProps {
-    data: ProductHistory[];
-}
-
-type ForecastMode = 'weekly' | 'monthly';
-type ServiceLevel = '85' | '90' | '95' | '100';
-
-export const ProductionForecastDashboard: React.FC<ProductionForecastDashboardProps> = ({ data }) => {
-    // State
-    const [selectedStore, setSelectedStore] = useState<string>('');
-    const [searchTerm, setSearchTerm] = useState('');
-    const [forecastMode, setForecastMode] = useState<ForecastMode>('weekly');
-    const [serviceLevel, setServiceLevel] = useState<ServiceLevel>('90');
-    const [dateRange, setDateRange] = useState<DateRange | undefined>();
-    
-    // Extract unique stores and add "All" option
-    const stores = useMemo(() => {
-        const uniqueStores = new Set(data.map(p => p.storeName));
-        const sortedStores = Array.from(uniqueStores).sort();
-        return ['Todas as lojas', ...sortedStores];
-    }, [data]);
-
-    // Set default store
-    useEffect(() => {
-        if (stores.length > 0 && !selectedStore) {
-            setSelectedStore(stores[0]); // Default to "Todas as lojas" if it's first
-        }
-    }, [stores, selectedStore]);
-
-    // Calculate Last Available Date for the Selected Store (or All)
-    const lastStoreDate = useMemo(() => {
-        if (!selectedStore) return new Date();
-
-        let relevantProducts = data;
-        if (selectedStore !== 'Todas as lojas') {
-            relevantProducts = data.filter(p => p.storeName === selectedStore);
-        }
-
-        let maxDate = new Date(0); // Epoch
-
-        relevantProducts.forEach(product => {
-            product.salesHistory.forEach(sale => {
-                const d = parseISO(sale.date);
-                if (isValid(d) && d > maxDate) {
-                    maxDate = d;
-                }
-            });
-        });
-
-        // If no data found, fallback to today
-        return maxDate.getTime() === 0 ? new Date() : maxDate;
-    }, [data, selectedStore]);
-
-    // Update Date Range when Store (and thus Last Date) changes
-    // Only set if not already set or if it seems out of sync
-    useEffect(() => {
-        if (lastStoreDate) {
-            setDateRange({
-                from: subDays(lastStoreDate, 90),
-                to: lastStoreDate
-            });
-        }
-    }, [lastStoreDate]);
-
-    // Calculate Production Plan
-    const productionPlan = useMemo(() => {
-        if (!selectedStore || !dateRange?.from || !dateRange?.to) return [];
-
-        const startDate = startOfDay(dateRange.from);
-        const endDate = endOfDay(dateRange.to);
-        
-        // Calculate number of full weeks in the selected range (Mon-Sun)
-        let weeksInInterval: Date[] = [];
-        try {
-            weeksInInterval = eachWeekOfInterval({
-                start: startDate,
-                end: endDate
-            }, { weekStartsOn: 1 }); // 1 = Monday
-        } catch (e) {
-            weeksInInterval = [];
-        }
-
-        const numberOfWeeks = Math.max(weeksInInterval.length, 1);
-        
-        // Filter by store FIRST (if not All)
-        let relevantProducts = data;
-        if (selectedStore !== 'Todas as lojas') {
-            relevantProducts = data.filter(p => p.storeName === selectedStore);
-        }
-
-        // Group by product code to aggregate across stores if needed
-        const aggregatedProducts = new Map<string, {
-            productName: string;
-            productCode: string;
-            category: string;
-            totalQty: number;
-            weeklySales: Map<string, number>; // Store weekly totals
-        }>();
-
-        relevantProducts.forEach(product => {
-            // Filter sales strictly within the time window
-            const relevantSales = product.salesHistory.filter(sale => {
-                const saleDate = parseISO(sale.date);
-                return saleDate >= startDate && saleDate <= endDate;
-            });
-
-            // Aggregate daily sales into weekly buckets
-            const productWeeklySales = new Map<string, number>();
-            relevantSales.forEach(sale => {
-                const saleDate = parseISO(sale.date);
-                const weekKey = `${getISOWeekYear(saleDate)}-W${getISOWeek(saleDate)}`;
-                productWeeklySales.set(weekKey, (productWeeklySales.get(weekKey) || 0) + sale.quantity);
-            });
-
-            const qty = relevantSales.reduce((acc, curr) => acc + curr.quantity, 0);
-
-            if (!aggregatedProducts.has(product.productCode)) {
-                aggregatedProducts.set(product.productCode, {
-                    productName: product.productName,
-                    productCode: product.productCode,
-                    category: product.category,
-                    totalQty: 0,
-                    weeklySales: new Map()
-                });
-            }
-
-            const current = aggregatedProducts.get(product.productCode)!;
-            current.totalQty += qty;
-            
-            // Merge weekly sales
-            productWeeklySales.forEach((val, key) => {
-                current.weeklySales.set(key, (current.weeklySales.get(key) || 0) + val);
-            });
-        });
-
-        // Convert to array and calculate stats
-        const plan = Array.from(aggregatedProducts.values()).map(item => {
-            const weeklyValues = Array.from(item.weeklySales.values());
-            
-            // Fill missing weeks with 0 to match numberOfWeeks
-            const weeksWithSales = weeklyValues.length;
-            const weeksWithZero = Math.max(0, numberOfWeeks - weeksWithSales);
-            const fullWeeklyValues = [...weeklyValues, ...Array(weeksWithZero).fill(0)];
-
-            const minWeekly = fullWeeklyValues.length > 0 ? Math.min(...fullWeeklyValues) : 0;
-            const maxWeekly = fullWeeklyValues.length > 0 ? Math.max(...fullWeeklyValues) : 0;
-            
-            // Calculate Mean
-            const sum = fullWeeklyValues.reduce((a, b) => a + b, 0);
-            const mean = sum / numberOfWeeks;
-
-            // Calculate Percentile
-            // 1. Sort values
-            fullWeeklyValues.sort((a, b) => a - b);
-            
-            // 2. Find index
-            const p = parseInt(serviceLevel) / 100;
-            const index = (fullWeeklyValues.length - 1) * p;
-            const lower = Math.floor(index);
-            const upper = Math.ceil(index);
-            const weight = index - lower;
-            
-            // 3. Interpolate
-            const percentileValue = fullWeeklyValues[lower] * (1 - weight) + fullWeeklyValues[upper] * weight;
-
-            // Suggested Production based on Service Level (Percentile)
-            const suggestedProduction = Math.ceil(percentileValue);
-
-            // Adjust for Monthly if needed
-            const finalMin = forecastMode === 'weekly' ? minWeekly : minWeekly * 4;
-            const finalMax = forecastMode === 'weekly' ? maxWeekly : maxWeekly * 4;
-            const finalAvg = forecastMode === 'weekly' ? mean : mean * 4;
-            const finalSuggested = forecastMode === 'weekly' ? suggestedProduction : suggestedProduction * 4;
-
-            return {
-                ...item,
-                minWeekly: finalMin,
-                maxWeekly: finalMax,
-                avgWeekly: finalAvg,
-                weeksAnalyzed: numberOfWeeks,
-                suggestedProduction: finalSuggested,
-                percentileValue
-            };
-        });
-
-        // Filter by search term
-        return plan.filter(p => 
-            p.productName.toLowerCase().includes(searchTerm.toLowerCase()) ||
-            p.category.toLowerCase().includes(searchTerm.toLowerCase())
-        ).sort((a, b) => b.suggestedProduction - a.suggestedProduction);
-
-    }, [data, selectedStore, dateRange, forecastMode, searchTerm, serviceLevel]);
-
-    // Export to Excel
-    const handleExport = () => {
-        const exportData = productionPlan.map(p => ({
-            'Produto': p.productName,
-            'Categoria': p.category,
-            'Vendas Totais (Período)': p.totalQty,
-            'Mínimo Semanal': p.minWeekly,
-            'Máximo Semanal': p.maxWeekly,
-            'Média Semanal': p.avgWeekly.toFixed(2),
-            [`Sugestão (${serviceLevel}%)`]: p.suggestedProduction,
-            'Semanas Analisadas': p.weeksAnalyzed,
-            'Loja': selectedStore
-        }));
-
-        const ws = XLSX.utils.json_to_sheet(exportData);
-        const wb = XLSX.utils.book_new();
-        XLSX.utils.book_append_sheet(wb, ws, "Plano de Produção");
-        XLSX.writeFile(wb, `Plano_Producao_${selectedStore.replace(/\s+/g, '_')}_${format(new Date(), 'dd-MM-yyyy')}.xlsx`);
-    };
-
-    return (
-        <div className="space-y-6 animate-in fade-in duration-500">
-            
-            {/* Context Alert */}
-            <Alert className="bg-amber-50 border-amber-200 dark:bg-amber-900/20 dark:border-amber-800">
-                <AlertCircle className="h-4 w-4 text-amber-600 dark:text-amber-400" />
-                <AlertTitle className="text-amber-800 dark:text-amber-300 font-bold">
-                    Dados Históricos: Última atualização em {format(lastStoreDate, 'dd/MM/yyyy')}
-                </AlertTitle>
-                <AlertDescription className="text-amber-700 dark:text-amber-400 text-xs mt-1">
-                    A previsão considera <strong>{productionPlan[0]?.weeksAnalyzed || 0} semanas completas (Seg-Dom)</strong>.
-                    A sugestão é baseada no <strong>Nível de Serviço de {serviceLevel}%</strong> (Percentil), garantindo estoque para {serviceLevel}% das semanas históricas.
-                </AlertDescription>
-            </Alert>
-
-            {/* Header Controls */}
-            <div className="flex flex-col xl:flex-row gap-4 justify-between items-end xl:items-center bg-white/50 p-4 rounded-xl border backdrop-blur-sm">
-                <div className="flex flex-col md:flex-row gap-4 w-full xl:w-auto">
-                    
-                    {/* Store Selector */}
-                    <div className="space-y-2 w-full md:w-[280px]">
-                        <label className="text-sm font-medium text-muted-foreground flex items-center gap-2">
-                            <Factory className="h-4 w-4" /> Loja
-                        </label>
-                        <Select value={selectedStore} onValueChange={setSelectedStore}>
-                            <SelectTrigger data-mia-filter="selected_store" data-mia-filter="selected_store">
-                                <SelectValue placeholder="Selecione a loja" />
-                            </SelectTrigger>
-                            <SelectContent>
-                                {stores.map(store => (
-                                    <SelectItem key={store} value={store}>{store}</SelectItem>
-                                ))}
-                            </SelectContent>
-                        </Select>
-                    </div>
-
-                    {/* Service Level Selector */}
-                    <div className="space-y-2 w-full md:w-[200px]">
-                        <label className="text-sm font-medium text-muted-foreground flex items-center gap-2">
-                            <ShieldCheck className="h-4 w-4" /> Nível de Serviço
-                        </label>
-                        <Select value={serviceLevel} onValueChange={(v: ServiceLevel) => setServiceLevel(v)}>
-                            <SelectTrigger>
-                                <SelectValue />
-                            </SelectTrigger>
-                            <SelectContent>
-                                <SelectItem value="85">85% (Conservador)</SelectItem>
-                                <SelectItem value="90">90% (Padrão)</SelectItem>
-                                <SelectItem value="95">95% (Agressivo)</SelectItem>
-                                <SelectItem value="100">100% (Cobrir Máximo)</SelectItem>
-                            </SelectContent>
-                        </Select>
-                    </div>
-
-                    {/* Forecast Mode Selector */}
-                    <div className="space-y-2 w-full md:w-[150px]">
-                        <label className="text-sm font-medium text-muted-foreground flex items-center gap-2">
-                            <Calculator className="h-4 w-4" /> Período
-                        </label>
-                        <Select value={forecastMode} onValueChange={(v: ForecastMode) => setForecastMode(v)}>
-                            <SelectTrigger>
-                                <SelectValue />
-                            </SelectTrigger>
-                            <SelectContent>
-                                <SelectItem value="weekly">Semanal</SelectItem>
-                                <SelectItem value="monthly">Mensal</SelectItem>
-                            </SelectContent>
-                        </Select>
-                    </div>
-
-                    {/* Date Range Picker */}
-                    <div className="space-y-2 w-full md:w-auto">
-                        <label className="text-sm font-medium text-muted-foreground flex items-center gap-2">
-                            <Calendar className="h-4 w-4" /> Histórico Analisado
-                        </label>
-                        <div className="flex items-center gap-2">
-                            <Popover>
-                                <PopoverTrigger asChild>
-                                    <Button
-                                        variant={"outline"}
-                                        className={cn(
-                                            "w-[240px] justify-start text-left font-normal",
-                                            !dateRange && "text-muted-foreground"
-                                        )}
-                                    >
-                                        <Calendar className="mr-2 h-4 w-4" />
-                                        {dateRange?.from ? (
-                                            dateRange.to ? (
-                                                <>
-                                                    {format(dateRange.from, "dd/MM/yyyy")} -{" "}
-                                                    {format(dateRange.to, "dd/MM/yyyy")}
-                                                </>
-                                            ) : (
-                                                format(dateRange.from, "dd/MM/yyyy")
-                                            )
-                                        ) : (
-                                            <span>Selecione o período</span>
-                                        )}
-                                    </Button>
-                                </PopoverTrigger>
-                                <PopoverContent className="w-auto p-0" align="start">
-                                    <CalendarUI
-                                        initialFocus
-                                        mode="range"
-                                        defaultMonth={dateRange?.from || lastStoreDate}
-                                        selected={dateRange}
-                                        onSelect={setDateRange}
-                                        numberOfMonths={2}
