-
-            {/* Main Content */}
-            <div className="grid gap-6">
-                <Card>
-                    <CardHeader>
-                        <CardTitle className="flex items-center gap-2">
-                            <Factory className="h-5 w-5 text-primary" />
-                            Plano de Produção {forecastMode === 'weekly' ? 'Semanal' : 'Mensal'} (Nível {serviceLevel}%)
-                        </CardTitle>
-                        <CardDescription>
-                            Análise de {productionPlan[0]?.weeksAnalyzed || 0} semanas completas (Seg-Dom) entre {dateRange?.from ? format(dateRange.from, 'dd/MM/yyyy') : ''} e {dateRange?.to ? format(dateRange.to, 'dd/MM/yyyy') : ''}
-                            {selectedStore === 'Todas as lojas' && ' - Agregado de todas as lojas'}
-                        </CardDescription>
-                    </CardHeader>
-                    <CardContent>

1	-- CMV (Custo de Mercadoria Vendida) por produto — módulo Financeiro.
2	-- Espelha a semântica de fichas_tecnicas / ficha_tecnica_itens (custo via trigger,
3	-- RLS authenticated sem isolamento por loja). CMV = custo UNITÁRIO da ficha técnica
4	-- (custo_calculado / rendimento_quantidade) + soma dos itens de CMV (embalagem/outros).
5	-- Fonte de verdade do custo: public.compute_item_cost / public.recompute_ficha_cost.
6	-- ADR: .harness/memory-bank/decisions/ADR-20260612-cmv-fichas.md
7	
8	-- ============================================================
9	-- 1. TABELAS
10	-- ============================================================
11	
12	CREATE TABLE IF NOT EXISTS public.cmv_fichas (
13	  id                bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
14	  nome              text        NOT NULL,
15	  ficha_tecnica_id  bigint      NOT NULL UNIQUE
16	                                REFERENCES public.fichas_tecnicas(id) ON DELETE CASCADE,
17	  status            text        NOT NULL DEFAULT 'rascunho',
18	  custo_calculado   numeric     DEFAULT 0,
19	  observacoes       text,
20	  created_by        uuid        REFERENCES auth.users(id),
21	  created_at        timestamptz NOT NULL DEFAULT now(),
22	  updated_at        timestamptz NOT NULL DEFAULT now()
23	);
24	
25	DO $$
26	BEGIN
27	  IF NOT EXISTS (
28	    SELECT 1 FROM pg_constraint
29	    WHERE conname = 'cmv_fichas_status_check'
30	      AND conrelid = 'public.cmv_fichas'::regclass
31	  ) THEN
32	    ALTER TABLE public.cmv_fichas
33	      ADD CONSTRAINT cmv_fichas_status_check
34	      CHECK (status IN ('rascunho', 'aprovada', 'obsoleta'));
35	  END IF;
36	END $$;
37	
38	CREATE TABLE IF NOT EXISTS public.cmv_itens (
39	  id                     bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
40	  cmv_id                 bigint  NOT NULL REFERENCES public.cmv_fichas(id) ON DELETE CASCADE,
41	  tipo                   text    NOT NULL DEFAULT 'embalagem',
42	  insumo_id              bigint  REFERENCES public.insumos(id) ON DELETE SET NULL,
43	  quantidade             numeric NOT NULL DEFAULT 0,
44	  unidade                text    NOT NULL DEFAULT 'un',
45	  preco_unitario_esboco  numeric,
46	  observacao             text,
47	  custo_calculado        numeric DEFAULT 0,
48	  ordem                  integer NOT NULL DEFAULT 0,
49	  created_at             timestamptz NOT NULL DEFAULT now(),
50	  updated_at             timestamptz NOT NULL DEFAULT now()
51	);
52	
53	DO $$
54	BEGIN
55	  IF NOT EXISTS (
56	    SELECT 1 FROM pg_constraint
57	    WHERE conname = 'cmv_itens_tipo_check'
58	      AND conrelid = 'public.cmv_itens'::regclass
59	  ) THEN
60	    ALTER TABLE public.cmv_itens
61	      ADD CONSTRAINT cmv_itens_tipo_check
62	      CHECK (tipo IN ('embalagem', 'outro'));
63	  END IF;
64	END $$;
65	
66	-- Posições do canvas CMV (ReactFlow). Tabela própria — NÃO reusa recipe_canvas_positions.
67	CREATE TABLE IF NOT EXISTS public.cmv_canvas_positions (
68	  cmv_id      bigint      NOT NULL REFERENCES public.cmv_fichas(id) ON DELETE CASCADE,
69	  node_type   text        NOT NULL,
70	  node_id     bigint      NOT NULL,
71	  x           numeric     NOT NULL,
72	  y           numeric     NOT NULL,
73	  updated_at  timestamptz NOT NULL DEFAULT now(),
74	  PRIMARY KEY (cmv_id, node_type, node_id)
75	);
76	
77	DO $$
78	BEGIN
79	  IF NOT EXISTS (
80	    SELECT 1 FROM pg_constraint
81	    WHERE conname = 'cmv_canvas_positions_node_type_check'
82	      AND conrelid = 'public.cmv_canvas_positions'::regclass
83	  ) THEN
