237	function CmvConfiguratorInner() {
238	  const navigate = useNavigate();
239	  const [searchParams] = useSearchParams();
240	  const cmvIdParam = searchParams.get('focus');
241	  const cmvId = cmvIdParam !== null && cmvIdParam !== '' ? parseInt(cmvIdParam, 10) : null;
