257	
258	  // Detail panel state
259	  const [selectedItemData, setSelectedItemData] = useState<RawCmvItem | null>(null);
260	  const [editQty, setEditQty] = useState('');
261	  const [editUnit, setEditUnit] = useState('');
262	  const [editPreco, setEditPreco] = useState('');
263	  const [editObs, setEditObs] = useState('');
264	  const [isSaving, setIsSaving] = useState(false);
265	  const [isDeleting, setIsDeleting] = useState(false);
266	
267	  // Add item dialog state
268	  const [isAddOpen, setIsAddOpen] = useState(false);
269	  const [newTipo, setNewTipo] = useState<TipoItem>('embalagem');
270	  const [newQty, setNewQty] = useState('1');
271	  const [newUnit, setNewUnit] = useState('un');
272	  const [newPreco, setNewPreco] = useState('');
273	  const [newObs, setNewObs] = useState('');
274	  const [isAddSaving, setIsAddSaving] = useState(false);
275	
276	  // -------------------------------------------------------------------------
277	  // Build ReactFlow nodes/edges from hook data
278	  // -------------------------------------------------------------------------
279	  const buildGraph = useCallback(() => {
280	    if (!cmv) return;
281	
282	    const newNodes: Node[] = [];
283	    const newEdges: Edge[] = [];
284	
285	    const rootId = cmvNodeId(cmv.id);
286	
287	    // Root node
288	    newNodes.push({
289	      id: rootId,
290	      type: 'cmv',
291	      data: { nome: cmv.nome, custo: cmv.custo_calculado, status: cmv.status, kind: 'cmv' } as Record<string, unknown>,
292	      position: positions.get(rootId) ?? { x: 800, y: 300 },
293	    });
294	
295	    // Ficha base node
296	    if (fichaData) {
297	      const fId = fichaNodeId(fichaData.id);
298	      const rendQty = fichaData.rendimento_quantidade || 1;
299	      const custoUnitario = (fichaData.custo_calculado ?? 0) / rendQty;
300	
301	      newNodes.push({
302	        id: fId,
303	        type: 'ficha',
304	        data: {
305	          nome: fichaData.nome,
306	          custoUnitario,
307	          rendimento: `${fichaData.rendimento_quantidade} ${fichaData.rendimento_unidade}`,
308	          status: fichaData.status,
309	          kind: 'ficha',
310	        } as Record<string, unknown>,
311	        position: positions.get(fId) ?? { x: 400, y: 300 },
312	      });
313	
314	      newEdges.push({
315	        id: `e-${fId}-${rootId}`,
316	        source: fId,
317	        target: rootId,
318	        animated: true,
319	        style: { stroke: '#F59E0B', strokeWidth: 3 },
320	      });
321	    }
322	
323	    // Item nodes
324	    const addedInsumoIds = new Set<number>();
325	
326	    items.forEach((item, idx) => {
327	      const itemId = `item_${item.id}`;
328	      const label = item.insumo?.nome ?? item.observacao ?? `Item ${idx + 1}`;
329	
330	      newNodes.push({
331	        id: itemId,
332	        type: 'cmvItem',
333	        data: {
334	          tipo: item.tipo as TipoItem,
335	          quantidade: item.quantidade,
336	          unidade: item.unidade,
337	          custo: item.custo_calculado,
338	          label,
339	          kind: 'cmvItem',
340	          _rawItemId: item.id,
341	        } as Record<string, unknown>,
342	        position: positions.get(itemId) ?? { x: 400, y: 100 + idx * 160 },
343	      });
344	
345	      newEdges.push({
346	        id: `e-${itemId}-${rootId}`,
347	        source: itemId,
348	        target: rootId,
349	        style: { stroke: '#52525b', strokeWidth: 2 },
350	      });
351	
352	      // Insumo linked to item
353	      if (item.insumo_id && !addedInsumoIds.has(item.insumo_id)) {
354	        addedInsumoIds.add(item.insumo_id);
355	        const insId = insumoNodeId(item.insumo_id);
356	        const insData = insumos.find((i) => i.id === item.insumo_id);
357	
358	        newNodes.push({
359	          id: insId,
360	          type: 'insumo',
361	          data: {
362	            nome: insData?.nome ?? 'Insumo',
363	            preco: insData?.preco_custo ?? null,
364	            unidade: insData?.unidade_compra ?? 'un',
365	            kind: 'insumo',
366	          } as Record<string, unknown>,
367	          position: positions.get(insId) ?? { x: 100, y: 100 + idx * 160 },
368	        });
369	
370	        newEdges.push({
371	          id: `e-${insId}-${itemId}`,
372	          source: insId,
373	          target: itemId,
374	          style: { stroke: '#7c3aed', strokeWidth: 1.5 },
375	        });
376	      }
377	    });
378	
379	    // Apply dagre layout for nodes without saved positions
380	    const hasAllPositions = newNodes.every((n) => positions.has(n.id));
381	    if (!hasAllPositions && newNodes.length > 0) {
382	      const laid = layoutGraph(newNodes, newEdges, 'LR');
383	      setNodes(laid);
384	    } else {
385	      setNodes(newNodes);
386	    }
387	    setEdges(newEdges);
388	
389	    setTimeout(() => {
390	      fitView({ padding: 0.12, duration: 400 });
391	    }, 80);
392	  }, [cmv, fichaData, items, insumos, positions, fitView, setNodes, setEdges]);
393	
394	  useEffect(() => {
395	    if (!loading) {
396	      buildGraph();
397	    }
398	  }, [loading, buildGraph]);
