401	  // Node drag → save position
402	  // -------------------------------------------------------------------------
403	  const handleNodeDragStop: NodeDragHandler = useCallback(
404	    (_evt, node) => {
405	      savePosition(node.id, node.position.x, node.position.y);
406	    },
