97	export function useCmvGraph(cmvId: number | null): CmvGraphData {
98	  const [loading, setLoading] = useState<boolean>(true);
99	  const [cmv, setCmv] = useState<RawCmv | null>(null);
100	  const [fichaData, setFichaData] = useState<RawCmvFicha | null>(null);
101	  const [items, setItems] = useState<RawCmvItem[]>([]);
102	  const [insumos, setInsumos] = useState<RawCmvInsumo[]>([]);
103	  const [notas, setNotas] = useState<RawCmvNF[]>([]);
104	  const [nfItems, setNfItems] = useState<RawCmvNFItem[]>([]);
105	  const [positions, setPositions] = useState<Map<string, { x: number; y: number }>>(new Map());
106	
107	  const fetchAll = useCallback(async () => {
108	    if (cmvId === null) {
109	      setLoading(false);
110	      return;
111	    }
112	
113	    setLoading(true);
114	
115	    try {
116	      const [
117	        cmvRes,
118	        itensRes,
119	        insumosRes,
120	        posRes,
121	        nfRes,
122	        nfItensRes,
123	      ] = await Promise.all([
124	        supabase
125	          .from('cmv_fichas')
126	          .select('*, fichas_tecnicas(*)')
127	          .eq('id', cmvId)
128	          .maybeSingle(),
129	        supabase
130	          .from('cmv_itens')
131	          .select('*, insumos(id,nome,preco_custo,unidade_compra,unidade_producao,categoria,fornecedor_principal)')
132	          .eq('cmv_id', cmvId)
133	          .order('ordem'),
134	        supabase
135	          .from('insumos')
136	          .select('id,nome,preco_custo,unidade_compra,unidade_producao,categoria,fornecedor_principal')
137	          .eq('ativo', true)
138	          .order('nome'),
139	        supabase
140	          .from('cmv_canvas_positions')
141	          .select('*')
142	          .eq('cmv_id', cmvId),
143	        supabase
144	          .from('notas_fiscais')
145	          .select('id,fornecedor,numero_nota,valor_total,data_nota')
146	          .order('data_nota', { ascending: false })
147	          .limit(80),
148	        supabase
149	          .from('itens_nota_fiscal')
150	          .select('id,nota_id,insumo_id,nome_produto,valor_unitario,peso_unitario,unidade_base,unidade')
151	          .not('insumo_id', 'is', null)
152	          .limit(2000),
153	      ]);
154	
155	      if (cmvRes.data) {
156	        const raw = cmvRes.data as Record<string, unknown>;
157	        setCmv({
158	          id: raw.id as number,
159	          nome: raw.nome as string,
160	          ficha_tecnica_id: raw.ficha_tecnica_id as number,
161	          status: raw.status as string,
162	          custo_calculado: raw.custo_calculado as number | null,
163	        });
164	
165	        if (raw.fichas_tecnicas) {
166	          const ft = raw.fichas_tecnicas;
167	          const ficha = Array.isArray(ft) ? ft[0] : ft;
168	          if (ficha) {
169	            const f = ficha as Record<string, unknown>;
170	            setFichaData({
171	              id: f.id as number,
172	              nome: f.nome as string,
173	              custo_calculado: f.custo_calculado as number | null,
174	              rendimento_quantidade: f.rendimento_quantidade as number,
175	              rendimento_unidade: f.rendimento_unidade as string,
176	              status: f.status as string,
177	            });
178	          }
179	        }
180	      } else {
181	        setCmv(null);
182	        setFichaData(null);
183	      }
184	
185	      if (itensRes.data) {
186	        const mappedItems = (itensRes.data as Record<string, unknown>[]).map((item) => {
187	          const insumosData = item.insumos;
188	          const insumoObj = insumosData
189	            ? Array.isArray(insumosData)
190	              ? insumosData[0]
191	              : insumosData
192	            : undefined;
193	          const mapped: RawCmvItem = {
194	            id: item.id as number,
195	            cmv_id: item.cmv_id as number,
196	            tipo: item.tipo as string,
197	            insumo_id: item.insumo_id as number | null,
198	            quantidade: item.quantidade as number,
199	            unidade: item.unidade as string,
200	            preco_unitario_esboco: item.preco_unitario_esboco as number | null,
201	            observacao: item.observacao as string | null,
202	            custo_calculado: item.custo_calculado as number | null,
203	            ordem: item.ordem as number,
204	            insumo: insumoObj as RawCmvInsumo | undefined,
205	          };
206	          return mapped;
207	        });
208	        setItems(mappedItems);
209	      } else {
210	        setItems([]);
211	      }
212	
213	      if (insumosRes.data) {
214	        setInsumos(insumosRes.data as unknown as RawCmvInsumo[]);
215	      }
216	
217	      if (posRes.data) {
218	        const newPositions = new Map<string, { x: number; y: number }>();
219	        for (const pos of posRes.data as Record<string, unknown>[]) {
220	          const key = `${pos.node_type}_${pos.node_id}`;
221	          newPositions.set(key, { x: pos.x as number, y: pos.y as number });
222	        }
223	        setPositions(newPositions);
224	      } else {
225	        setPositions(new Map());
226	      }
227	
228	      if (nfRes.data) {
229	        setNotas(nfRes.data as unknown as RawCmvNF[]);
230	      }
231	
232	      if (nfItensRes.data) {
233	        setNfItems(nfItensRes.data as unknown as RawCmvNFItem[]);
234	      }
235	    } catch (err) {
236	      console.error('[useCmvGraph] fetchAll error:', err);
237	    } finally {
238	      setLoading(false);
239	    }
240	  }, [cmvId]);
241	
242	  useEffect(() => {
243	    fetchAll();
244	  }, [fetchAll]);
245	
246	  const savePosition = useCallback(
247	    async (key: string, x: number, y: number) => {
248	      if (cmvId === null) return;
249	
250	      const parsed = parseNodeId(key);
251	      if (!parsed) return;
252	
253	      // Update local state optimistically
254	      setPositions((prev) => {
255	        const next = new Map(prev);
256	        next.set(key, { x, y });
257	        return next;
258	      });
259	
260	      try {
261	        const { error } = await supabase
262	          .from('cmv_canvas_positions')
263	          .upsert(
264	            {
265	              cmv_id: cmvId,
266	              node_type: parsed.type,
267	              node_id: parsed.id,
268	              x,
269	              y,
270	            },
271	            { onConflict: 'cmv_id,node_type,node_id' },
272	          );
273	
274	        if (error) {
275	          console.error('[useCmvGraph] savePosition error:', error);
276	        }
277	      } catch (err) {
278	        console.error('[useCmvGraph] savePosition exception:', err);
279	      }
280	    },
281	    [cmvId],
282	  );
283	
284	  return {
285	    loading,
286	    cmv,
287	    fichaData,
288	    items,
289	    insumos,
290	    notas,
291	    nfItems,
292	    positions,
293	    savePosition,
294	    refetch: fetchAll,
295	  };
296	}
